const d=v=>v?new Date(v).toLocaleDateString('es-MX'):'—';
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const DIAS=['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
const parseHorario=(v='')=>{const [dias='',rango='']=String(v).split('|').map(x=>x.trim());const [inicio='',fin='']=rango.split('-').map(x=>x.trim());return {dias:dias?dias.split(',').map(x=>x.trim()).filter(Boolean):['Lunes','Martes','Miércoles','Jueves','Viernes'],inicio:/^\d{2}:\d{2}$/.test(inicio)?inicio:'08:00',fin:/^\d{2}:\d{2}$/.test(fin)?fin:'17:00'};};

async function api(path,options={}){
  const headers={...H(),...(options.headers||{})};
  if(options.body && !(options.body instanceof FormData)) headers['Content-Type']='application/json';
  const r=await fetch(`${API_BASE}/estadias${path}`,{...options,headers});
  const j=await r.json().catch(()=>({ok:false,mensaje:'Respuesta inválida'}));
  if(!r.ok||j.ok===false) throw new Error(j.mensaje||'No se pudo completar la operación.');
  return j;
}
async function authApi(path,options={}){
  const headers={...H(),...(options.headers||{})};
  if(options.body && !(options.body instanceof FormData)) headers['Content-Type']='application/json';
  const r=await fetch(`${API_BASE}/auth${path}`,{...options,headers});
  const j=await r.json().catch(()=>({ok:false,mensaje:'Respuesta inválida'}));
  if(!r.ok||j.ok===false) throw new Error(j.mensaje||'No se pudo completar la operación.');
  return j;
}

